import{_ as o,C as s,o as n,c as i,j as a,a as r,E as c,a3 as p}from"./chunks/framework.DEy3KOfk.js";const v=JSON.parse('{"title":"Waypoints","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/waypoints/docs/index.md"},"headers":[],"relativePath":"packages/waypoints/docs/index.md","filePath":"packages/waypoints/docs/index.md","lastUpdated":1791428389000}'),d={name:"packages/waypoints/docs/index.md"},l={id:"waypoints",tabindex:"-1",class:"component-page-title"},h={class:"component-page-title__version"};function m(u,e,y,w,_,f){const t=s("Badge");return n(),i("div",null,[a("h1",l,[e[0]||(e[0]=a("img",{class:"component-page-title__icon",src:"/pumpkin-plugins/packages/waypoints/icon.svg",alt:"","aria-hidden":"true",width:"48",height:"48"},null,-1)),e[1]||(e[1]=a("span",{class:"component-page-title__text"},[r("Waypoints "),a("a",{class:"header-anchor",href:"#waypoints","aria-label":'Permalink to "Waypoints"'},"​")],-1)),a("span",h,[c(t,{type:"info",text:"v0.0.0"})])]),e[2]||(e[2]=p('<p>Waypoints stores named block positions on the server and lets players share them with public or allowlist access. Java players can also show accessible waypoints in the vanilla Locator Bar.</p><p>Install <code>waypoints.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory and restart. Waypoints are private by default. The plugin has no config file; it stores versioned records in <code>plugins/data/Waypoints/waypoints.json</code>.</p><h2 id="create-and-find-a-waypoint" tabindex="-1">Create and find a waypoint <a class="header-anchor" href="#create-and-find-a-waypoint" aria-label="Permalink to &quot;Create and find a waypoint&quot;">​</a></h2><p>Use <code>/wp mark &quot;Home Base&quot;</code> to save your current block, or <code>/wp add &quot;Home Base&quot; 120 64 -30</code> to save coordinates. <code>/wp list</code> lists waypoints in the current dimension; <code>/wp list all</code> includes other dimensions. Use the UUID shown in the output for operations such as <code>/wp show &lt;id&gt;</code> and <code>/wp remove &lt;id&gt;</code>.</p><h2 id="share-access" tabindex="-1">Share access <a class="header-anchor" href="#share-access" aria-label="Permalink to &quot;Share access&quot;">​</a></h2><p>Owners can keep a waypoint private, make it public, or switch it to allowlist access. Invite and revoke online players by name; access records store their player UUIDs. Players can only inspect or send waypoints they are allowed to access. Operators have separate admin commands to list or remove any saved waypoint.</p><h2 id="locator-and-map-clients" tabindex="-1">Locator and map clients <a class="header-anchor" href="#locator-and-map-clients" aria-label="Permalink to &quot;Locator and map clients&quot;">​</a></h2><p>Locator output is opt-in for each waypoint. It is sent only to Java players who can access the waypoint and are in its dimension. Bedrock Locator Bar output is unsupported by the pinned Pumpkin API. The registered <code>xaero-share</code> adapter currently reports unavailable, so send commands return readable coordinates and do not claim client import or automatic map synchronization.</p><p>The store is preserved and writes stop if its JSON is malformed or uses an unsupported schema; fix the file before expecting changes to persist.</p>',9))])}const k=o(d,[["render",m]]);export{v as __pageData,k as default};
